import { PanelLeft, PanelLeftClose, Plus } from "lucide-react";
import { type FormEvent, useState } from "react";

import type { Session } from "../types";

interface SessionRailProps {
  sessions: Session[];
  selectedId: string | null;
  runningIds: Set<string>;
  onSelect: (id: string) => void;
  onCreate: (title: string, workspace?: string) => Promise<void>;
}

export function SessionRail({ sessions, selectedId, runningIds, onSelect, onCreate }: SessionRailProps) {
  const [expanded, setExpanded] = useState(false);
  const [open, setOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [workspace, setWorkspace] = useState("");
  const [creating, setCreating] = useState(false);

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    const value = title.trim();
    if (!value) return;
    setCreating(true);
    try {
      await onCreate(value, workspace.trim() || undefined);
      setTitle("");
      setWorkspace("");
      setOpen(false);
    } finally {
      setCreating(false);
    }
  };

  if (!expanded) {
    return (
      <aside className="rail rail--mini">
        <button className="icon" onClick={() => setExpanded(true)} title="Sessions" type="button">
          <PanelLeft size={15} />
        </button>
        <div className="rail__minis">
          {sessions.slice(0, 12).map((s) => (
            <button
              className={`rail__mini ${s.id === selectedId ? "on" : ""}`}
              key={s.id}
              onClick={() => onSelect(s.id)}
              title={s.title}
              type="button"
            >
              {runningIds.has(s.id) && <i className="dot dot--live" />}
              {s.title.slice(0, 1).toUpperCase()}
            </button>
          ))}
        </div>
      </aside>
    );
  }

  return (
    <aside className="rail">
      <div className="rail__head">
        <button className="icon" onClick={() => setExpanded(false)} type="button">
          <PanelLeftClose size={15} />
        </button>
        <span>Sessions</span>
        <button className="icon" onClick={() => setOpen(!open)} title="New session" type="button">
          <Plus size={14} />
        </button>
      </div>
      {open && (
        <form className="rail__new rail__new--col" onSubmit={submit}>
          <input
            autoFocus
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Title"
            value={title}
          />
          <input
            onChange={(e) => setWorkspace(e.target.value)}
            placeholder="workspace path (optional)"
            value={workspace}
          />
          <button disabled={!title.trim() || creating} type="submit">
            +
          </button>
        </form>
      )}
      <div className="rail__list">
        {sessions.map((s) => (
          <button
            className={`rail__item ${s.id === selectedId ? "on" : ""}`}
            key={s.id}
            onClick={() => onSelect(s.id)}
            type="button"
          >
            <span className="rail__title">{s.title}</span>
            <span className="rail__meta">
              {runningIds.has(s.id) && <i className="dot dot--live" />}
              {s.workspace ? s.workspace.split(/[\\/]/).filter(Boolean).pop() : s.model ?? "—"}
            </span>
          </button>
        ))}
      </div>
    </aside>
  );
}
