import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Brain, FileDiff, KeyRound, Network, Terminal, Wrench } from "lucide-react";
import { lazy, Suspense, useEffect, useMemo, useState } from "react";
import { Group, Panel, Separator } from "react-resizable-panels";

import { createSession, graphSnapshot, listProviders, listSessions } from "./api";
import { ChangesPanel } from "./components/ChangesPanel";
import { Conversation } from "./components/Conversation";
import { MemoryPanel } from "./components/MemoryPanel";
import { ProviderPanel } from "./components/ProviderPanel";
import { SessionRail } from "./components/SessionRail";
import { ToolsPanel } from "./components/ToolsPanel";
import { emptyLive, useAgentEvents } from "./hooks/useAgentEvents";

const GraphView = lazy(() => import("./components/GraphView").then((m) => ({ default: m.GraphView })));
const QueryConsole = lazy(() =>
  import("./components/QueryConsole").then((m) => ({ default: m.QueryConsole })),
);

type Tab = "graph" | "changes" | "tools" | "memory" | "providers" | "query";

const TABS: { id: Tab; label: string; icon: typeof Network }[] = [
  { id: "graph", label: "Graph", icon: Network },
  { id: "changes", label: "Changes", icon: FileDiff },
  { id: "tools", label: "Tools", icon: Wrench },
  { id: "memory", label: "Memory", icon: Brain },
  { id: "providers", label: "Providers", icon: KeyRound },
  { id: "query", label: "Query", icon: Terminal },
];

export default function App() {
  const [tab, setTab] = useState<Tab>("graph");
  const [fullscreen, setFullscreen] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const queryClient = useQueryClient();
  const live = useAgentEvents();

  const sessionsQuery = useQuery({ queryKey: ["sessions"], queryFn: listSessions });
  const graphQuery = useQuery({ queryKey: ["graph"], queryFn: graphSnapshot });
  const create = useMutation({
    mutationFn: createSession,
    onSuccess: async (s) => {
      setSelectedId(s.id);
      await queryClient.invalidateQueries({ queryKey: ["sessions"] });
      await queryClient.invalidateQueries({ queryKey: ["graph"] });
    },
  });

  const sessions = sessionsQuery.data ?? [];
  const snapshot = graphQuery.data ?? { nodes: [], edges: [] };
  const selected = sessions.find((s) => s.id === selectedId) ?? null;
  const providersQuery = useQuery({ queryKey: ["providers"], queryFn: () => listProviders(false) });
  const connectedProviders = (providersQuery.data ?? []).filter((p) => p.connected);
  const running = useMemo(
    () => new Set(Object.entries(live).filter(([, v]) => v.running).map(([k]) => k)),
    [live],
  );

  useEffect(() => {
    if (!selectedId && sessions.length > 0) setSelectedId(sessions[0]!.id);
  }, [sessions, selectedId]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && fullscreen) setFullscreen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [fullscreen]);

  const inspector = (
    <section className="inspector">
      <Suspense fallback={<div className="panel__empty">…</div>}>
        {tab === "graph" && (
          <GraphView
            fullscreen={fullscreen}
            onSelectSession={setSelectedId}
            onToggleFullscreen={() => setFullscreen((f) => !f)}
            selectedSessionId={selectedId}
            snapshot={snapshot}
          />
        )}
        {tab === "changes" && <ChangesPanel sessionId={selectedId} />}
        {tab === "tools" && <ToolsPanel />}
        {tab === "memory" && <MemoryPanel />}
        {tab === "providers" && <ProviderPanel />}
        {tab === "query" && <QueryConsole />}
      </Suspense>
    </section>
  );

  return (
    <div className="app">
      <header className="top">
        <div>
          <span className="wordmark">rennew</span>
          <span className="top__sub">{selected?.title ?? ""}</span>
        </div>
        <nav className="tabs">
          {TABS.map(({ id, label, icon: Icon }) => (
            <button className={tab === id ? "on" : ""} key={id} onClick={() => setTab(id)} type="button">
              <Icon size={14} />
              <span>{label}</span>
            </button>
          ))}
        </nav>
        <div className="top__right">
          {connectedProviders.length > 0 ? (
            <span className="muted" style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
              <i className="dot dot--on" />
              {connectedProviders.map((p) => p.id).join(", ")}
            </span>
          ) : (
            <button className="link" onClick={() => setTab("providers")} type="button">
              connect a provider
            </button>
          )}
        </div>
      </header>

      {fullscreen ? (
        <div className="body body--full">{inspector}</div>
      ) : (
        <Group className="body" orientation="horizontal">
          <Panel defaultSize="16" minSize="12" maxSize="26">
            <SessionRail
              onCreate={async (title, workspace) => {
                await create.mutateAsync({ title, workspace });
              }}
              onSelect={setSelectedId}
              runningIds={running}
              selectedId={selectedId}
              sessions={sessions}
            />
          </Panel>
          <Separator className="handle" />
          <Panel defaultSize="46" minSize="30">
            <Conversation
              live={selectedId ? live[selectedId] ?? emptyLive : emptyLive}
              onOpenProviders={() => setTab("providers")}
              onSessionCreated={(s) => setSelectedId(s.id)}
              session={selected}
            />
          </Panel>
          <Separator className="handle" />
          <Panel defaultSize="38" minSize="24">{inspector}</Panel>
        </Group>
      )}
    </div>
  );
}
